rameter_of_direction_ne_zero {L : LdParams} +    {bound : ℕ} (line : LineDesc L) (hdir : line.direction ≠ 0) +    (poly : DegPoly L bound) (param : ScalarQ L) : +    evalOpt line (line.base + param • line.direction) poly = +      some (evalCoefficient poly param) := by +  apply WinImplications.evalOpt_eq_some_of_evaluatesTo +  refine ⟨⟨param, rfl⟩, ?_⟩ +  intro other heq +  have hsmul : param • line.direction = other • line.direction := +    add_left_cancel heq +  have hsub : (param - other) • line.direction = 0 := by +    rw [sub_smul, hsmul, sub_self] +  have hparam : param = other := +    sub_eq_zero.mp ((smul_eq_zero.mp hsub).resolve_right hdir) +  rw [hparam] + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Lines/AxisLineResampling.lean b/MIPStarRE/QPBT/Combining/Lines/AxisLineResampling.lean new file mode 100644 index 00000000..fd764e57 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Lines/AxisLineResampling.lean @@ -0,0 +1,63 @@ +import MIPStarRE.QPBT.Combining.Lines.RestrictedAverage +import MIPStarRE.QPBT.Combining.Lines.SubLineUniform + +/-! +# Axis line-point parameter resampling + +This module records that a uniformly sampled point on an axis-parallel line +may be resampled by an independent uniform affine parameter without changing +the joint line-point expectation. + +## References + +The resampling is used at +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:955`; the +axis line-point law is `def:line-point-dist` at +`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:274-287`. +-/ + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT + +noncomputable section + +/-- Resampling a uniform affine parameter on the sampled axis line preserves +the joint axis line-point law. This is the axis case of the conditional +sampling used at paper line 955. -/ +theorem avgOver_aLinePointDist_resample_parameter (L : LdParams) +    (value : (LineDesc L × (Fin L.m → ScalarQ L)) → ℝ) : +    avgOver (aLinePointDist L) value = +    avgOver (aLinePointDist L) (fun sample => +      avgOver (uniformDistribution (ScalarQ L)) (fun param => +        value (sample.1, sample.1.base + param • sample.1.direction))) := by +  classical +  unfold aLinePointDist clDistribution +  simp only [Distribution.avgOver_map, aLineDescOf_ldALineCL] +  have hblock := uniformDistribution_map_equiv (ldSpaceBlockEquiv L).symm +  rw [← hblock] +  simp only [Distribution.avgOver_map] +  rw [uniformDistribution_prod] +  simp only [SandwichProduct.avgOver_distribution_prod] +  rw [avgOver_comm, avgOver_comm (uniformDistribution (Fin L.m → ScalarQ L))] +  apply congrArg +  funext block +  let direction : Fin L.m → ScalarQ L := +    coordinateDirection (chiIndex L block.1) +  change avgOver (uniformDistribution (Fin L.m → ScalarQ L)) (fun point => +      value (LineDesc.axis (lineRepMap direction point) block.1 +        (lineRepMap_apply_self direction point), point)) = +    avgOver (uniformDistribution (Fin L.m → ScalarQ L)) (fun point => +      avgOver (uniformDistribution (ScalarQ L)) (fun param => +        value (LineDesc.axis (lineRepMap direction point) block.1 +          (lineRepMap_apply_self direction point), +          lineRepMap direction point + param • direction))) +  have haxis := avgOver_uniform_lineRepMap_resample_parameter direction +    (fun base point => value (LineDesc.axis +      (lineRepMap direction base) block.1 +      (lineRepMap_apply_self _ _), point)) +  simpa only [lineRepMap_apply_self] using haxis + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Lines/DiagonalResampling.lean b/MIPStarRE/QPBT/Combining/Lines/DiagonalResampling.lean index ad310b14..27d3a0de 100644 --- a/MIPStarRE/QPBT/Combining/Lines/DiagonalResampling.lean +++ b/MIPStarRE/QPBT/Combining/Lines/DiagonalResampling.lean @@ -39,7 +39,7 @@ theorem avgOver_dLinePointDist_resample_parameter (L : LdParams)    rw [← hblock]    simp only [Distribution.avgOver_map]    rw [uniformDistribution_prod] -  simp only [avgOver_prod] +  simp only [SandwichProduct.avgOver_distribution_prod]    rw [avgOver_comm, avgOver_comm (uniformDistribution (Fin L.m -> ScalarQ L))]    apply congrArg    funext block @@ -49,20 +49,6 @@ theorem avgOver_dLinePointDist_resample_parameter (L : LdParams)        direction index = 0 := by      intro index hindex      simp [direction, prefixProjection, hindex] -  have hresample (direction : Fin L.m -> ScalarQ L) -      (quantity : (Fin L.m -> ScalarQ L) -> -        (Fin L.m -> ScalarQ L) -> ℝ) : -      avgOver (uniformDistribution (Fin L.m -> ScalarQ L)) -          (fun point => quantity (lineRepMap direction point) point) = -        avgOver (uniformDistribution (Fin L.m -> ScalarQ L)) (fun point => -          avgOver (uniformDistribution (ScalarQ L)) (fun param => -            quantity (lineRepMap direction point) -              (lineRepMap direction point + param • direction))) := by -    have hmap := uniformDistribution_map_lineRepMap_add_smul direction -    have havg := congrArg (fun dist => avgOver dist -      (fun point => quantity (lineRepMap direction point) point)) hmap -    rw [Distribution.avgOver_map, uniformDistribution_prod, avgOver_prod] at havg -    simpa only [lineRepMap_add_smul, lineRepMap_apply_self] using havg.symm    change avgOver (uniformDistribution (Fin L.m -> ScalarQ L)) (fun point =>        value (LineDesc.diagonal (lineRepMap direction point) block.1 direction          (lineRepMap_apply_self direction point) hprefix, point)) = @@ -71,7 +57,7 @@ theorem avgOver_dLinePointDist_resample_parameter (L : LdParams)          value (LineDesc.diagonal (lineRepMap direction point) block.1 direction            (lineRepMap_apply_self direction point) hprefix,            lineRepMap direction point + param • direction))) -  have h := hresample direction +  have h := avgOver_uniform_lineRepMap_resample_parameter direction      (fun base point => value (LineDesc.diagonal        (lineRepMap direction base) block.1 direction        (lineRepMap_apply_self direction base) hprefix, point)) diff --git a/MIPStarRE/QPBT/Combining/Lines/FiberCollision.lean b/MIPStarRE/QPBT/Combining/Lines/FiberCollision.lean new file mode 100644 index 00000000..4d7692ee --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Lines/FiberCollision.lean @@ -0,0 +1,57 @@ +import MIPStarRE.QPBT.Combining.Lines.WeightedCollision + +/-! +# Collision bounds on a fixed nondegenerate line fiber + +This module specializes the weighted collision estimate for the mixed +line-point distribution to the indicator of one fixed line. + +## References + +The estimate is the Schwartz--Zippel step in `lem:qld-xz-lines`, +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:950-955`. +-/ + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT + +noncomputable section + +/-- On each nonzero-direction line fiber the collision mass is at most the +degree-to-field-size ratio times the fiber mass. Thus division by any positive +fiber mass gives the conditional probability required by `lem:pasting`. This +proof-only estimate supports paper `14_analysis_of_the_pauli_basis_test.tex:955`; +transport to the product law and the pasting register presentation is separate. -/ +theorem linePointDist_nondegenerate_fiber_collision_le {L : LdParams} {bound : ℕ} +    (line : LineDesc L) (hdir : line.direction ≠ 0) +    (first second : DegPoly L bound) (hne : first ≠ second) : +    avgOver (linePointDist L) (fun sample => +      if sample.1 = line then +        (if evalOpt sample.1 sample.2 first = evalOpt sample.1 sample.2 second +          then 1 else 0) else 0) ≤ +      (bound : ℝ) / Fintype.card (ScalarQ L) * +        avgOver (linePointDist L) (fun sample => if sample.1 = line then 1 else 0) := by +  classical +  have hweight (other : LineDesc L) : (0 : ℝ) ≤ if other = line then 1 else 0 := by +    split_ifs <;> norm_num +  have hbound := linePointDist_nondegenerate_weighted_collision_le +    (fun other => if other = line then 1 else 0) +    hweight first second hne +  have hleft (sample : LineDesc L × (Fin L.m → ScalarQ L)) : +      (if sample.1.direction ≠ 0 then (if sample.1 = line then (1 : ℝ) else 0) * +        (if evalOpt sample.1 sample.2 first = evalOpt sample.1 sample.2 second +          then 1 else 0) else 0) = +      (if sample.1 = line then +        (if evalOpt sample.1 sample.2 first = evalOpt sample.1 sample.2 second +          then 1 else 0) else 0) := by +    by_cases heq : sample.1 = line <;> simp [heq, hdir] +  have hright (sample : LineDesc L × (Fin L.m → ScalarQ L)) : +      (if sample.1.direction ≠ 0 then (if sample.1 = line then (1 : ℝ) else 0) else 0) = +        (if sample.1 = line then 1 else 0) := by +    by_cases heq : sample.1 = line <;> simp [heq, hdir] +  simpa only [hleft, hright] using hbound + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Lines/MixedResampling.lean b/MIPStarRE/QPBT/Combining/Lines/MixedResampling.lean new file mode 100644 index 00000000..019ca154 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Lines/MixedResampling.lean @@ -0,0 +1,40 @@ +import MIPStarRE.QPBT.Combining.Lines.AxisLineResampling +import MIPStarRE.QPBT.Combining.Lines.DiagonalResampling + +/-! +# Mixed line-point parameter resampling + +This module combines the axis and diagonal resampling identities for the equal +mixture defining the line-point distribution. + +## References + +The resampling supports the Schwartz-Zippel step in `lem:qld-xz-lines`, +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:950-955`. The +mixed line-point law is `def:line-point-dist` in +`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:274-287`. +-/ + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT + +noncomputable section + +/-- Resampling a uniform affine parameter on a sampled line preserves the +unconditional mixed line-point law, including zero-direction diagonal fibers. +This formalization-only identity combines the axis and diagonal cases of the +conditional sampling used at paper line 955. -/ +theorem avgOver_linePointDist_resample_parameter (L : LdParams) +    (value : (LineDesc L × (Fin L.m → ScalarQ L)) → ℝ) : +    avgOver (linePointDist L) value = +      avgOver (linePointDist L) (fun sample => +        avgOver (uniformDistribution (ScalarQ L)) (fun param => +          value (sample.1, sample.1.base + param • sample.1.direction))) := by +  rw [linePointDist, avgOver_mix, avgOver_mix] +  rw [avgOver_aLinePointDist_resample_parameter L value, +    avgOver_dLinePointDist_resample_parameter L value] + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Lines/PointwiseDefect.lean b/MIPStarRE/QPBT/Combining/Lines/PointwiseDefect.lean new file mode 100644 index 00000000..213f3856 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Lines/PointwiseDefect.lean @@ -0,0 +1,54 @@ +import MIPStarRE.QPBT.Combining.Points.Placement + +/-! +# Pointwise consistency defect bound + +This module records the unit upper bound for the pointwise consistency defect +of complete measurements placed on opposite expanded registers. + +## References + +This is a proof-only bound used when restoring discarded sampling mass in +`lem:qld-xz-lines`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:950-963`. +-/ + +open scoped BigOperators MatrixOrder ComplexOrder + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum + +noncomputable section + +/-- The pointwise defect of complete measurements on opposite registers is at +most one: it equals one minus a nonnegative diagonal overlap. This proof-only +bound restores discarded mass graded by the ambient line-point distribution. -/ +theorem consistencyDefect_integrand_le_one {P : AdmissibleParams} {ε : ℝ} +    {Outcome : Type*} [Fintype Outcome] [DecidableEq Outcome] +    (S : ProjectiveSetting P ε) (p1 p2 : Placement) (hopp : p1.IsOpposite p2) +    (first : Measurement Outcome (S.ExpandedLocalSpace p1.side)) +    (second : Measurement Outcome (S.ExpandedLocalSpace p2.side)) : +   