agrees with polynomial +evaluation at the unique affine parameter. -/ +theorem evalOpt_affine_parameter_of_direction_ne_zero {L : LdParams} +    {bound : ℕ} (line : LineDesc L) (hdir : line.direction ≠ 0) +    (poly : DegPoly L bound) (param : ScalarQ L) : +    evalOpt line (line.base + param • line.direction) poly = +      some (evalCoefficient poly param) := by +  apply WinImplications.evalOpt_eq_some_of_evaluatesTo +  refine ⟨⟨param, rfl⟩, ?_⟩ +  intro other heq +  have hsmul : param • line.direction = other • line.direction := +    add_left_cancel heq +  have hsub : (param - other) • line.direction = 0 := by +    rw [sub_smul, hsmul, sub_self] +  have hparam : param = other := +    sub_eq_zero.mp ((smul_eq_zero.mp hsub).resolve_right hdir) +  rw [hparam] + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Lines/AxisLineResampling.lean b/MIPStarRE/QPBT/Combining/Lines/AxisLineResampling.lean new file mode 100644 index 00000000..fd764e57 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Lines/AxisLineResampling.lean @@ -0,0 +1,63 @@ +import MIPStarRE.QPBT.Combining.Lines.RestrictedAverage +import MIPStarRE.QPBT.Combining.Lines.SubLineUniform + +/-! +# Axis line-point parameter resampling + +This module records that a uniformly sampled point on an axis-parallel line +may be resampled by an independent uniform affine parameter without changing +the joint line-point expectation. + +## References + +The resampling is used at +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:955`; the +axis line-point law is `def:line-point-dist` at +`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:274-287`. +-/ + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT + +noncomputable section + +/-- Resampling a uniform affine parameter on the sampled axis line preserves +the joint axis line-point law. This is the axis case of the conditional +sampling used at paper line 955. -/ +theorem avgOver_aLinePointDist_resample_parameter (L : LdParams) +    (value : (LineDesc L × (Fin L.m → ScalarQ L)) → ℝ) : +    avgOver (aLinePointDist L) value = +    avgOver (aLinePointDist L) (fun sample => +      avgOver (uniformDistribution (ScalarQ L)) (fun param => +        value (sample.1, sample.1.base + param • sample.1.direction))) := by +  classical +  unfold aLinePointDist clDistribution +  simp only [Distribution.avgOver_map, aLineDescOf_ldALineCL] +  have hblock := uniformDistribution_map_equiv (ldSpaceBlockEquiv L).symm +  rw [← hblock] +  simp only [Distribution.avgOver_map] +  rw [uniformDistribution_prod] +  simp only [SandwichProduct.avgOver_distribution_prod] +  rw [avgOver_comm, avgOver_comm (uniformDistribution (Fin L.m → ScalarQ L))] +  apply congrArg +  funext block +  let direction : Fin L.m → ScalarQ L := +    coordinateDirection (chiIndex L block.1) +  change avgOver (uniformDistribution (Fin L.m → ScalarQ L)) (fun point => +      value (LineDesc.axis (lineRepMap direction point) block.1 +        (lineRepMap_apply_self direction point), point)) = +    avgOver (uniformDistribution (Fin L.m → ScalarQ L)) (fun point => +      avgOver (uniformDistribution (ScalarQ L)) (fun param => +        value (LineDesc.axis (lineRepMap direction point) block.1 +          (lineRepMap_apply_self direction point), +          lineRepMap direction point + param • direction))) +  have haxis := avgOver_uniform_lineRepMap_resample_parameter direction +    (fun base point => value (LineDesc.axis +      (lineRepMap direction base) block.1 +      (lineRepMap_apply_self _ _), point)) +  simpa only [lineRepMap_apply_self] using haxis + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Lines/DiagonalResampling.lean b/MIPStarRE/QPBT/Combining/Lines/DiagonalResampling.lean index ad310b14..27d3a0de 100644 --- a/MIPStarRE/QPBT/Combining/Lines/DiagonalResampling.lean +++ b/MIPStarRE/QPBT/Combining/Lines/DiagonalResampling.lean @@ -39,7 +39,7 @@ theorem avgOver_dLinePointDist_resample_parameter (L : LdParams)    rw [← hblock]   