sc.diagonal        (lineRepMap direction base) block.1 direction        (lineRepMap_apply_self direction base) hprefix, point)) diff --git a/MIPStarRE/QPBT/Combining/Lines/FiberCollision.lean b/MIPStarRE/QPBT/Combining/Lines/FiberCollision.lean new file mode 100644 index 00000000..4d7692ee --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Lines/FiberCollision.lean @@ -0,0 +1,57 @@ +import MIPStarRE.QPBT.Combining.Lines.WeightedCollision + +/-! +# Collision bounds on a fixed nondegenerate line fiber + +This module specializes the weighted collision estimate for the mixed +line-point distribution to the indicator of one fixed line. + +## References + +The estimate is the Schwartz--Zippel step in `lem:qld-xz-lines`, +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:950-955`. +-/ + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT + +noncomputable section + +/-- On each nonzero-direction line fiber the collision mass is at most the +degree-to-field-size ratio times the fiber mass. Thus division by any positive +fiber mass gives the conditional probability required by `lem:pasting`. This +proof-only estimate supports paper `14_analysis_of_the_pauli_basis_test.tex:955`; +transport to the product law and the pasting register presentation is separate. -/ +theorem linePointDist_nondegenerate_fiber_collision_le {L : LdParams} {bound : ℕ} +    (line : LineDesc L) (hdir : line.direction ≠ 0) +    (first second : DegPoly L bound) (hne : first ≠ second) : +    avgOver (linePointDist L) (fun sample => +      if sample.1 = line then +        (if evalOpt sample.1 sample.2 first = evalOpt sample.1 sample.2 second +          then 1 else 0) else 0) ≤ +      (bound : ℝ) / Fintype.card (ScalarQ L) * +        avgOver (linePointDist L) (fun sample => if sample.1 = line then 1 else 0) := by +  classical +  have hweight (other : LineDesc L) : (0 : ℝ) ≤ if other = line then 1 else 0 := by +    split_ifs <;> norm_num +  have hbound := linePointDist_nondegenerate_weighted_collision_le +    (fun other => if other = line then 1 else 0) +    hweight first second hne +  have hleft (sample : LineDesc L × (Fin L.m → ScalarQ L)) : +      (if sample.1.direction ≠ 0 then (if sample.1 = line then (1 : ℝ) else 0) * +        (if evalOpt sample.1 sample.2 first = evalOpt sample.1 sample.2 second +          then 1 else 0) else 0) = +      (if sample.1 = line then +        (if evalOpt sample.1 sample.2 first = evalOpt sample.1 sample.2 second +          then 1 else 0) else 0) := by +    by_cases heq : sample.1 = line <;> simp [heq, hdir] +  have hright (sample : LineDesc L × (Fin L.m → ScalarQ L)) : +      (if sample.1.direction ≠ 0 then (if sample.1 = line then (1 : ℝ) else 0) else 0) = +        (if sample.1 = line then 1 else 0) := by +    by_cases heq : sample.1 = line <;> simp [heq, hdir] +  simpa only [hleft, hright] using hbound + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Lines/MixedResampling.lean b/MIPStarRE/QPBT/Combining/Lines/MixedResampling.lean new file mode 100644 index 00000000..019ca154 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Lines/MixedResampling.lean @@ -0,0 +1,40 @@ +import MIPStarRE.QPBT.Combining.Lines.AxisLineResampling +import MIPStarRE.QPBT.Combining.Lines.DiagonalResampling + +/-! +# Mixed line-point parameter resampling + +This module combines the axis and diagonal resampling identities for the equal +mixture defining the line-point distribution. + +## References + +The resampling supports the Schwartz-Zippel step in `lem:qld-xz-lines`, +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:950-955`. The +mixed line-point law is `def:line-point-dist` in +`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:274-287`. +-/ + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT + +noncomputable section + +/-- Resampling a uniform affine parameter on a sampled line preserves the +unconditional mixed line-point law, including zero-direction diagonal fibers. +This formalization-only identity combines the axis and diagonal cases of the +conditional sampling used at paper line 955. -/ +theorem avgOver_linePointDist_resample_parameter (L : LdParams) +    (value : (LineDesc L × (Fin L.m → ScalarQ L)) → ℝ) : +    avgOver (linePointDist L) value = +      avgOver (linePointDist L) (fun sample => +        avgOver (uniformDistribution (ScalarQ L)) (fun param => +          value (sample.1, sample.1.base + param • sample.1.direction))) := by +  rw [linePointDist, avgOver_mix, avgOver_mix] +  rw [avgOver_aLinePointDist_resample_parameter L value, +    avgOver_dLinePointDist_resample_parameter L value] + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Lines/PointwiseDefect.lean b/MIPStarRE/QPBT/Combining/Lines/PointwiseDefect.lean new file mode 100644 index 00000000..213f3856 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Lines/PointwiseDefect.lean @@ -0,0 +1,54 @@ +import MIPStarRE.QPBT.Combining.Points.Placement + +/-! +# Pointwise consistency defect bound + +This module records the unit upper bound for the pointwise consistency defect +of complete measurements placed on opposite expanded registers. + +## References + +This is a proof-only bound used when restoring discarded sampling mass in +`lem:qld-xz-lines`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:950-963`. +-/ + +open scoped BigOperators MatrixOrder ComplexOrder + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum + +noncomputable section + +/-- The pointwise defect of complete measurements on opposite registers is at +most one: it equals one minus a nonnegative diagonal overlap. This proof-only +bound restores discarded mass graded by the ambient line-point distribution. -/ +theorem consistencyDefect_integrand_le_one {P : AdmissibleParams} {ε : ℝ} +    {Outcome : Type*} [Fintype Outcome] [DecidableEq Outcome] +    (S : ProjectiveSetting P ε) (p1 p2 : Placement) (hopp : p1.IsOpposite p2) +    (first : Measurement Outcome (S.ExpandedLocalSpace p1.side)) +    (second : Measurement Outcome (S.ExpandedLocalSpace p2.side)) : +    (∑ answer : Outcome, ∑ other : Outcome, +      if answer = other then 0 else DistanceCalculus.stateQForm S.psiHat +        (S.place p1 (first.effect answer) * S.place p2 (second.effect other))) ≤ 1 := by +  have h := DistanceCalculus.point_defect_eq +    (S.placedMeasurement p1 first) (S.placedMeasurement p2 second) S.psiHat +  simp only [ProjectiveSetting.placedMeasurement_effect, S.psiHat_norm, one_pow] at h +  rw [h] +  have hproduct (answer : Outcome) : +      0 ≤ S.place p1 (first.effect answer) * S.place p2 (second.effect answer) := by +    exact Commute.mul_nonneg +      (S.place_nonneg p1 (first.pos answer)) +      (S.place_nonneg p2 (second.pos answer)) +      (S.place_comm p1 p2 hopp _ _) +  have hdiag : 0 ≤ ∑ answer : Outcome, DistanceCalculus.stateQForm S.psiHat +      (S.place p1 (first.effect answer) * S.place p2 (second.effect answer)) := +    Finset.sum_nonneg fun answer _ => DistanceCalculus.stateQForm_nonneg _ +      (hproduct answer) +  linarith + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Lines/PolynomialCollision.lean b/MIPStarRE/QPBT/Combining/Lines/PolynomialCollision.lean new file mode 100644 index 00000000..b1586adc --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Lines/PolynomialCollision.lean @@ -0,0 +1,33 @@ +import MIPStarRE.QPBT.Observables.LineDefs +import Mathlib.Algebra.Polynomial.OfFn +import Mathlib.Algebra.Polynomial.Roots + +/-! +# Collision bounds for coefficient polynomials + +This module identifies coefficient-list evaluation with Mathlib polynomial +evaluation. The root-count bound `evalCoefficient_collision_card_le` is +imported from `Algebra.Coefficients`, where it is stated for finite integral +domains and therefore applies to the scalar field of every line descriptor. + +## References + +The lemmas support the Schwartz-Zippel step in `lem:qld-xz-lines`, +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:950-955`. +-/ + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT + +/-- The Mathlib polynomial associated to a coefficient tuple has the specified +evaluation. This formalization-only identity connects the coefficient +convention to the root bound used at paper +`14_analysis_of_the_pauli_basis_test.tex:955`. -/ +theorem polynomial_ofFn_eval_eq_evalCoefficient {K : Type*} [CommSemiring K] +    [DecidableEq K] {size : ℕ} (coeffs : Fin size -> K) (param : K) : +    (Polynomial.ofFn size coeffs).eval param = evalCoefficient coeffs param := by +  simp [Polynomial.ofFn_eq_sum_monomial, Polynomial.eval_finsetSum, +    Polynomial.eval_monomial, evalCoefficient] + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean b/MIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean index afea195c..7ae26c48 100644 --- a/MIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean +++ b/MIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean @@ -83,21 +83,6 @@ theorem avgOver_mix {α : Type*} [DecidableEq α] (t : ℝ) (ht0 : 0 ≤ t)      (t * μ.weight a + (1 - t) * ν.weight a) * f a) = _    rw [hsplit, hμ, hν]   -/-- Formalization-only auxiliary: an average against a product law is the -iterated average.  Blueprint `lem:restricted-line-mixture-bounds`, paper -`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1056-1058`. -/ -theorem avgOver_prod {α β : Type*} [DecidableEq α] [DecidableEq β] -    (μ : Distribution α) (ν : Distribution β) (f : α × β → ℝ) : -    avgOver (Distribution.prod μ ν) f = -      avgOver μ (fun a => avgOver ν (fun b => f (a, b))) := by -  classical -  unfold avgOver -  change (∑ p ∈ μ.support ×ˢ ν.support, μ.weight p.1 * ν.weight p.2 * f p) = _ -  rw [Finset.sum_product] -  refine Finset.sum_congr rfl fun a _ => ?_ -  rw [Finset.mul_sum] -  exact Finset.sum_congr rfl fun b _ => by ring -  /-- Formalization-only auxiliary: one component of a uniform mixture carries at  most the whole nonnegative average, scaled by its mixture w