.card (ScalarQ L) := by +  classical +  simp_rw [evalOpt_affine_parameter_of_direction_ne_zero line hdir, +    Option.some.injEq] +  have hcard := evalCoefficient_collision_card_le first second hne +  unfold avgOver +  simp only [uniformDistribution_support, uniformDistribution_weight_apply, +    mul_ite, mul_one, mul_zero, ← Finset.sum_filter] +  rw [Finset.sum_const, nsmul_eq_mul, mul_one_div] +  exact div_le_div_of_nonneg_right (by exact_mod_cast hcard) (by positivity) + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Lines/WeightedCollision.lean b/MIPStarRE/QPBT/Combining/Lines/WeightedCollision.lean new file mode 100644 index 00000000..522a04f8 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Lines/WeightedCollision.lean @@ -0,0 +1,55 @@ +import MIPStarRE.QPBT.Combining.Lines.MixedResampling +import MIPStarRE.QPBT.Combining.Lines.UniformAffineCollision + +/-! +# Weighted collision bounds for sampled lines + +This module lifts the uniform affine-parameter collision estimate to the mixed +line-point distribution with an arbitrary nonnegative weight depending only on +the sampled line. + +## References + +The estimate is the Schwartz--Zippel step in `lem:qld-xz-lines`, +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:950-955`. +-/ + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT + +noncomputable section + +/-- The collision bound remains valid with any nonnegative weight depending +only on the line, after restricting to nonzero directions. This proof-only +estimate is the conditional form of the root argument in `lem:qld-xz-lines`, +paper lines 950--955; it does not assert the false unrestricted collision bound +on zero-direction coefficient presentations. -/ +theorem linePointDist_nondegenerate_weighted_collision_le {L : LdParams} +    {bound : ℕ} (weight : LineDesc L → ℝ) +    (hweight : ∀ line, 0 ≤ weight line) (first second : DegPoly L bound) +    (hne : first ≠ second) : +    avgOver (linePointDist L) (fun sample => +      if samp