es_and_mipstar.tex:514-524`. -/ +theorem pastedMeasurement_isMeasurement {Γ₁ Γ₂ ι : Type*} +    [Fintype Γ₁] [Fintype Γ₂] [Fintype ι] [DecidableEq ι] +    (G₁ : Measurement Γ₁ ι) (G₂ : Measurement Γ₂ ι) +    (hG₂ : MIPStarRE.QPBT.Measurement.IsProjective G₂) : +    (∀ g : Γ₁ × Γ₂, +      0 ≤ pastedMeasurement G₁.effect G₂.effect g.1 g.2) ∧ +      (∑ g : Γ₁ × Γ₂, +        pastedMeasurement G₁.effect G₂.effect g.1 g.2) = 1 := by +  constructor +  · intro g +    unfold pastedMeasurement +    apply Matrix.nonneg_iff_posSemidef.mpr +    have hpos : ((G₂.effect g.2)ᴴ * G₁.effect g.1 * G₂.effect g.2).PosSemidef := +      (Matrix.nonneg_iff_posSemidef.mp (G₁.pos g.1)).conjTranspose_mul_mul_same +        (G₂.effect g.2) +    rw [MIPStarRE.QPBT.DistanceCalculus.measurement_effect_hermitian G₂ g.2] at hpos +    exact hpos +  · classical +    unfold pastedMeasurement +    rw [Fintype.sum_prod_type, Finset.sum_comm] +    calc +      (∑ g₂ : Γ₂, ∑ g₁ : Γ₁, +          G₂.effect g₂ * G₁.effect g₁ * G₂.effect g₂) = +          ∑ g₂ : Γ₂, +            G₂.effect g₂ * (∑ g₁ : Γ₁, G₁.effect g₁) * G₂.effect g₂ := by +        apply Finset.sum_congr rfl +        intro g₂ _ +        rw [Finset.mul_sum, Finset.sum_mul] +      _ = ∑ g₂ : Γ₂, G₂.effect g₂ := by +        apply Finset.sum_congr rfl +        intro g₂ _ +        rw [G₁.sum_eq_one, mul_one, (hG₂ g₂).isIdempotentElem.eq] +      _ = 1 := G₂.sum_eq_one + +namespace Pasting + +variable {ιA ιB : Type*} +  [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB] + +/-- Adjoin a fixed basis vector to each local register. Alice's original +coordinate is first and Bob's original coordinate is last. This is the +common-carrier realization used for the heterogeneous pasting estimate; +blueprint `def:pasting-product-state`. -/ +noncomputable def productPaddedState (a₀ : ιA) (b₀ : ιB) +    (ψ : EuclideanSpace ℂ (ιA × ιB)) : +    EuclideanSpace ℂ ((ιA × ιB) × (ιA × ιB)) := +  WithLp.toLp 2 (fun p => if p.1.2 = b₀ then +    if p.2.1 = a₀ then ψ (p.1.1, p.2.2) else 0 else 0) + +/-- Adjoining unit basis vectors preserves the state norm. Formalization-only +auxiliary, blueprint `lem:pasting-product-state-preservation`. -/ +theorem productPaddedState_norm (a₀ : ιA) (b₀ : ιB) +    (ψ : EuclideanSpace ℂ (ιA × ιB)) : +    ‖productPaddedState a₀ b₀ ψ‖ = ‖ψ‖ := by +  rw [← sq_eq_sq₀ (norm_nonneg _) (norm_nonneg _)] +  simp [EuclideanSpace.norm_sq_eq, productPaddedState, Fintype.sum_prod_type, apply_ite] + +/-- Local tensor padding preserves every bipartite quadratic form. This exact +identity is independent of positivity and of normalization of the state. +Formalization-only auxiliary, blueprint `lem:pasting-product-state-preservation`. -/ +theorem stateQForm_productPaddedState (a₀ : ιA) (b₀ : ιB) +    (ψ : EuclideanSpace ℂ (ιA × ιB)) (A : Op ιA) (B : Op ιB) : +    stateQForm (productPaddedState a₀ b₀ ψ) +        (heteroKron (heteroKron A (1 : Op ιB)) (heteroKron (1 : Op ιA) B)) = +      stateQForm ψ (heteroKron A B) := by +  unfold stateQForm applyOperatorToState +  rw [EuclideanSpace.inner_eq_star_dotProduct, EuclideanSpace.inner_eq_star_dotProduct] +  apply congrArg Complex.re +  simp [productPaddedState, Matrix.toEuclideanLin, Matrix.mulVec, dotProduct, +    heteroKron, Matrix.kronecker, Matrix.kroneckerMap_apply, Fintype.sum_prod_type, +    Matrix.one_apply, Finset.sum_mul, apply_ite] + +/-- Tensor padding preserves the off-diagonal consistency defect for arbitrary +operator families. No measurement or probability assumption is required. +Formalization-only auxiliary, blueprint `lem:pasting-product-state-preservation`. -/ +theorem consistencyDefect_productPaddedState {X α : Type*} +    [Fintype X] [DecidableEq X] [Fintype α] [DecidableEq α] +    (D : Distribution X) (A : X → α → Op ιA) (B : X → α → Op ιB) +    (a₀ : ιA) (b₀ : ιB) (ψ : EuclideanSpace ℂ (ιA × ιB)) : +    consistencyDefect D +        (fun x a => heteroKron (heteroKron (A x a) (1 : Op ιB)) (1 : Op (ιA × ιB))) +        (fun x a => heteroKron (1 : 