t).effect a₁) 1) +          (fun q a₁ => heteroKron 1 (((G₁ q.1.1).postprocess +            (fun g => eval₁ g q.1.2)).effect a₁)) ψ ≤ δ → +        consistencyDefect D +          (fun q a₂ => heteroKron (((A q).postprocess Prod.snd).effect a₂) 1) +          (fun q a₂ => heteroKron 1 (((G₂ q.1.1).postprocess +            (fun g => eval₂ g q.2)).effect a₂)) ψ ≤ δ → +        consistencyDefect D (fun q a => heteroKron ((A q).effect a) 1) +          (fun q a => heteroKron 1 (∑ g₁ : Γ₁, ∑ g₂ : Γ₂, +            if (eval₁ g₁ q.1.2, eval₂ g₂ q.2) = a then +              pastedMeasurement (fun g => (G₁ q.1.1).effect g) +                (fun g => (G₂ q.1.1).effect g) g₁ g₂ else 0)) ψ ≤ δp η δ := by +  classical +  obtain ⟨C, hC1, hCbound⟩ := exists_coarse_commutator_bound +  refine ⟨fun x y => (3 * C + 19) * (x ^ (1/4 : ℝ) + y ^ (1/8 : ℝ)), ?_, ?_⟩ +  · refine ⟨3 * C + 19, 1/4, 1/8, by linarith, by norm_num, by norm_num, ?_⟩ +    intro x y hx hy +    exact ⟨mul_nonneg (by linarith) +      (add_nonneg (Real.rpow_nonneg hx _) (Real.rpow_nonneg hy _)), le_rfl⟩ +  intro X Y₁ Y₂ R₁ R₂ Γ₁ Γ₂ ι _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ +    D eval₁ eval₂ G₁ G₂ A ψ η δ hD hψ hη hδ hG₂ hA hcoll h₁ h₂ +  have hpm : ∀ q : (X × Y₁) × Y₂, +      (∀ g : Γ₁ × Γ₂, 0 ≤ pastedMeasurement (fun g => (G₁ q.1.1).effect g) +          (fun g => (G₂ q.1.1).effect g) g.1 g.2) ∧ +        (∑ g : Γ₁ × Γ₂, pastedMeasurement (fun g => (G₁ q.1.1).effect g) +          (fun g => (G₂ q.1.1).effect g) g.1 g.2) = 1 := +    fun q => pastedMeasurement_isMeasurement (G₁ q.1.1) (G₂ q.1.1) (hG₂ q.1.1) +  set Bp : ((X × Y₁) × Y₂) → Measurement (R₁ × R₂) ι := fun q => +    (Measurement.ofSumEqOne +      (fun g : Γ₁ × Γ₂ => pastedMeasurement (fun g => (G₁ q.1.1).effect g) +        (fun g => (G₂ q.1.1).effect g) g.1 g.2) (hpm q).1 (hpm q).2).postprocess +      (fun g => (eval₁ g.1 q.1.2, eval₂ g.2 q.2)) with hBpdef +  have heff : ∀ (q : (X × Y₁) × Y₂) (a : R₁ × R₂), (Bp q).effect a = +      ∑ g₁ : Γ₁, ∑ g₂ : Γ₂, if (eval₁ g₁ q.1.2, 