n q a₁ => heteroKron 1 (((G₁ q.1.1).postprocess +            (fun g => eval₁ g q.1.2)).effect a₁)) ψ ≤ δ → +        consistencyDefect D +          (fun q a₂ => heteroKron (((A q).postprocess Prod.snd).effect a₂) 1) +          (fun q a₂ => heteroKron 1 (((G₂ q.1.1).postprocess +            (fun g => eval₂ g q.2)).effect a₂)) ψ ≤ δ → +        consistencyDefect D (fun q a => heteroKron ((A q).effect a) 1) +          (fun q a => heteroKron 1 (∑ g₁ : Γ₁, ∑ g₂ : Γ₂, +            if (eval₁ g₁ q.1.2, eval₂ g₂ q.2) = a then +              pastedMeasurement (fun g => (G₁ q.1.1).effect g) +                (fun g => (G₂ q.1.1).effect g) g₁ g₂ else 0)) ψ ≤ δp η δ := by +  classical +  obtain ⟨δp, hpoly, hbound⟩ := exists_pasting_error_of_marginal_consistency +  refine ⟨δp, hpoly, ?_⟩ +  intro X Y₁ Y₂ R₁ R₂ Γ₁ Γ₂ ιA ιB _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ +    D eval₁ eval₂ G₁ G₂ A ψ η δ hD hψ hη hδ hG₂ hA hcoll h₁ h₂ +  have hnonempty : Nonempty (ιA × ιB) := by +    rcases isEmpty_or_nonempty (ιA × ιB) with h | h +    · letI := h +      have hz : ψ = 0 := Subsingleton.elim _ _ +      simp [hz] at hψ +    · exact h +  obtain ⟨⟨a₀, b₀⟩⟩ := hnonempty +  let A' := fun q => Measurement.leftPlacement (ιB := ιB) (A q) +  let G₁' := fun x => Measurement.rightPlacement (ιA := ιA) (G₁ x) +  let G₂' := fun x => Measurement.rightPlacement (ιA := ιA) (G₂ x) +  let ψ' := Pasting.productPaddedState a₀ b₀ ψ +  have hψ' : ‖ψ'‖ = 1 := (Pasting.productPaddedState_norm a₀ b₀ ψ).trans hψ +  have h₁' : consistencyDefect D +      (fun q a₁ => heteroKron (((A' q).postprocess Prod.fst).effect a₁) 1) +      (fun q a₁ => heteroKron 1 (((G₁' q.1.1).postprocess +        (fun g => eval₁ g q.1.2)).effect a₁)) ψ' ≤ δ := by +    simpa only [A', G₁', ψ', ← Measurement.leftPlacement_postprocess, +      ← Measurement.rightPlacement_postprocess, Measurement.leftPlacement_effect, +      Measurement.rightPlacement_effect, Pasting.consistencyDefect_productPaddedState] using h₁ +  have h₂' : consistencyDefect D +      (