1262		The distribution $D_{\mathrm{ALine}}$ is a uniform mixture of the
1263		distributions $D_{\mathrm{ALine},i}$ for $i \in \{0, \dots, m-1\}$, and
1264		likewise $D_{\mathrm{DLine}}$ is a uniform mixture of the
1265		$D_{\mathrm{DLine},i}$. As a consequence:
1266		\begin{enumerate}
1267			\item any approximation that holds on average over the line-point
1268			distribution $D_{\mathrm{Line}}$ with error $\delta$ holds over each
1269			restricted distribution $D_{\mathrm{ALine},i}$ and
1270			$D_{\mathrm{DLine},i}$ with error $2m\delta$;
1271			\item any approximation that holds on average over
1272			$D_{\mathrm{Line}} \times D_{\mathrm{Line}}$ holds over any product
1273			of restricted distributions with error $4m^2\delta$;
1274			\item in particular, by Lemma~\ref{lem:qld-xz-lines}, for any types
1275			$\mathrm{v}_1, \mathrm{v}_2 \in \{\mathrm{ALine},
1276			\mathrm{DLine}\}$ and any $i, j \in \{0, \dots, m-1\}$,
1277			\begin{equation}
1278				\label{eq:qld-xz-lines-restricted}
1279				\E_{(\ell_X,x) \sim D_{\mathrm{v}_1,i}}\
1280				\E_{(\ell_Z,z) \sim D_{\mathrm{v}_2,j}}
1281				\sum_{f_X,f_Z}
1282				\bra{\hat\psi}
1283				\big(T^{\ell_X,\ell_Z}_{f_X,f_Z}\big)_{\mathsf{A}\mathsf{A}'}
1284				\ot
1285				\big(\Id - \hat{Q}^{x,z}_{f_X(x),f_Z(z)}
1286				\big)_{\mathsf{B}\mathsf{A}''}
1287				\ket{\hat\psi}
1288				= O(m^2 \delta_P)\,.
1289			\end{equation}
1290		\end{enumerate}
1291	\end{lemma}
